SELECT * FROM (SELECT r.*, COALESCE((SELECT MAX(s.last_seq) FROM conversations s WHERE s.root_id=r.id AND s.archived_at IS NULL AND s.closed_at IS NULL),r.last_seq,0) AS activity FROM conversations r WHERE r.parent_id IS NULL AND r.archived_at IS NULL AND r.closed_at IS NULL AND NOT EXISTS (SELECT 1 FROM tasks t WHERE t.id=r.task_id AND t.status IN ('done','closed') AND NOT (EXISTS (SELECT 1 FROM conversations s JOIN messages m ON m.conversation_id=s.id WHERE s.root_id=r.id AND m.kind<>'notice' AND m.deleted_at IS NULL AND m.restricted=0 AND m.legacy_audience IS NULL AND m.created_at>COALESCE((SELECT MAX(h.created_at) FROM history_events h WHERE h.subject_type='task' AND h.subject_id=t.id AND h.kind='move' AND h.new IN (SELECT id FROM stages WHERE kind IN ('done','closed'))),t.closed_at,t.done_at,t.updated_at) AND (COALESCE(s.root_id,s.id) IN (SELECT r.id FROM conversations r WHERE CASE WHEN r.audience IS NULL THEN (CASE COALESCE(r.scope,'direct') WHEN 'personal' THEN COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben' AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'shared' THEN (CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN substr(r.room_key,1,instr(r.room_key||':',':')-1) ELSE (SELECT substr(value,5) FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'bot:%' LIMIT 1) END) IN ('cpo','ops','product-design') ELSE EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') END OR (r.kind='task' AND r.task_id IS NOT NULL)) ELSE CASE r.audience WHEN 'company' THEN 1 WHEN 'team' THEN r.audience_group_id IN () WHEN 'members' THEN EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben')) WHEN 'task' THEN r.task_id IS NOT NULL WHEN 'home' THEN COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) IS NOT NULL AND COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) NOT IN () WHEN 'personal' THEN ((COALESCE(r.room_key,'')<>'' AND COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben') OR EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben'))) AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'participants' THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') WHEN 'meeting' THEN 0 ELSE 0 END END) OR s.id IN (SELECT lm.conversation_id FROM messages lm JOIN conversations lr ON lr.id=lm.conversation_id WHERE lr.audience='home' AND lm.legacy_audience IN ('shared:cpo','shared:ops','shared:product-design'))) AND (s.task_id IS NULL OR s.task_id IN (SELECT id FROM tasks))))) AND (COALESCE(r.root_id,r.id) IN (SELECT r.id FROM conversations r WHERE CASE WHEN r.audience IS NULL THEN (CASE COALESCE(r.scope,'direct') WHEN 'personal' THEN COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben' AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'shared' THEN (CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN substr(r.room_key,1,instr(r.room_key||':',':')-1) ELSE (SELECT substr(value,5) FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'bot:%' LIMIT 1) END) IN ('cpo','ops','product-design') ELSE EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') END OR (r.kind='task' AND r.task_id IS NOT NULL)) ELSE CASE r.audience WHEN 'company' THEN 1 WHEN 'team' THEN r.audience_group_id IN () WHEN 'members' THEN EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben')) WHEN 'task' THEN r.task_id IS NOT NULL WHEN 'home' THEN COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) IS NOT NULL AND COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) NOT IN () WHEN 'personal' THEN ((COALESCE(r.room_key,'')<>'' AND COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben') OR EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben'))) AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'participants' THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') WHEN 'meeting' THEN 0 ELSE 0 END END) OR r.id IN (SELECT lm.conversation_id FROM messages lm JOIN conversations lr ON lr.id=lm.conversation_id WHERE lr.audience='home' AND lm.legacy_audience IN ('shared:cpo','shared:ops','shared:product-design'))) AND (r.task_id IS NULL OR r.task_id IN (SELECT id FROM tasks)) AND ((COALESCE(r.audience,CASE WHEN substr(COALESCE(r.room_key,''),1,13)='live-meeting:' THEN 'meeting' WHEN r.scope='personal' THEN 'personal' WHEN r.scope='shared' THEN 'home' WHEN r.kind='task' AND r.task_id IS NOT NULL THEN 'task' ELSE 'participants' END) IN ('company','team','members','personal','participants','task') AND ((r.owner_id='human:ben' OR EXISTS (SELECT 1 FROM thread_members im WHERE im.thread_id=r.id AND im.actor IN ('human:ben')) OR r.id IN (SELECT COALESCE(s.root_id,s.id) FROM thread_followers f JOIN conversations s ON s.id=f.thread_id WHERE f.actor='human:ben' AND f.following=1 AND s.archived_at IS NULL AND s.closed_at IS NULL) OR EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben')) OR (EXISTS (SELECT 1 FROM thread_pins p WHERE p.thread_id=r.id AND p.actor='human:ben' AND p.pinned=1) OR (r.pinned_for_everyone_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM thread_pins p WHERE p.thread_id=r.id AND p.actor='human:ben' AND p.pinned=0))))) OR (COALESCE(r.audience,CASE WHEN substr(COALESCE(r.room_key,''),1,13)='live-meeting:' THEN 'meeting' WHEN r.scope='personal' THEN 'personal' WHEN r.scope='shared' THEN 'home' WHEN r.kind='task' AND r.task_id IS NOT NULL THEN 'task' ELSE 'participants' END)='home' AND r.owner_id='human:ben') OR r.id IN (SELECT value FROM json_each('[]'))) AND (r.id IN (SELECT value FROM json_each('[]')) OR (r.id NOT IN (SELECT value FROM json_each('[]')) AND (EXISTS (SELECT 1 FROM conversations s LEFT JOIN thread_followers f ON f.thread_id=s.id AND f.actor='human:ben' JOIN messages m INDEXED BY messages_thread_human ON m.conversation_id=s.id AND m.seq>MAX(COALESCE(f.last_read_seq,0),0) WHERE s.root_id=r.id AND s.archived_at IS NULL AND s.closed_at IS NULL AND s.last_unread_seq>MAX(COALESCE(f.last_read_seq,0),0) AND m.sender_id LIKE 'human:%' AND m.sender_id<>'human:ben' AND m.deleted_at IS NULL) OR r.id IN (SELECT s.root_id FROM message_deliveries d JOIN messages m ON m.id=d.message_id JOIN conversations s ON s.id=d.thread_id LEFT JOIN thread_followers f ON f.thread_id=s.id AND f.actor=d.recipient WHERE d.recipient='human:ben' AND d.state IN ('pending','delivered','capped','held') AND NOT (d.recipient LIKE 'human:%' AND ((m.sender_id='keeper' AND COALESCE(json_extract(CASE WHEN json_valid(m.refs) THEN m.refs END,'$.task'),'')<>'') OR ((m.sender_id LIKE 'bot:%' AND m.kind IN ('say','notice','ask') AND EXISTS (SELECT 1 FROM tasks t WHERE t.conversation_id=m.conversation_id)) AND COALESCE(d.reason,'') NOT IN ('mention','reply','follower')))) AND s.archived_at IS NULL AND s.closed_at IS NULL AND m.seq>MAX(COALESCE(f.last_read_seq,0),0) AND m.sender_id<>'human:ben' AND m.deleted_at IS NULL)))) AND (r.id IN (SELECT value FROM json_each('[]')) OR NOT EXISTS (SELECT 1 FROM thread_followers mf WHERE mf.thread_id=r.id AND mf.actor='human:ben' AND mf.notify='muted')) AND NOT r.id IN (SELECT value FROM json_each('[]'))) ORDER BY activity DESC, id DESC LIMIT 100
